'use client';

import React, { useEffect, useRef, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import dynamic from 'next/dynamic';

const AgoraRTC = dynamic(() => import('agora-rtc-sdk-ng'), { ssr: false });

const APP_ID = 'fd0e77a2c15f4c53af85276a8910ed8a';

const CoworkingRoom = () => {
  const [roomId] = useState(uuidv4());
  const [client, setClient] = useState(null);
  const [localAudioTrack, setLocalAudioTrack] = useState(null);
  const [localVideoTrack, setLocalVideoTrack] = useState(null);
  const localVideoRef = useRef(null);

  useEffect(() => {
    const initAgora = async () => {
      const AgoraRTC = (await import('agora-rtc-sdk-ng')).default;
      const agoraClient = AgoraRTC.createClient({ mode: 'rtc', codec: 'vp8' });

      setClient(agoraClient);

      const tokenRes = await fetch(`/api/agora-token?channelName=${roomId}`);
      const { token } = await tokenRes.json();

      await agoraClient.join(APP_ID, roomId, token, null);

      const [microphoneTrack, cameraTrack] = await AgoraRTC.createMicrophoneAndCameraTracks();
      setLocalAudioTrack(microphoneTrack);
      setLocalVideoTrack(cameraTrack);

      cameraTrack.play(localVideoRef.current);

      await agoraClient.publish([microphoneTrack, cameraTrack]);
    };

    initAgora();

    return () => {
      if (client) {
        localAudioTrack?.stop();
        localAudioTrack?.close();
        localVideoTrack?.stop();
        localVideoTrack?.close();
        client.leave();
      }
    };
  }, []);

  return (
    <div className="p-6">
      <h1 className="text-xl font-bold mb-4">Welcome to Room: {roomId}</h1>
      <div>
        <div ref={localVideoRef} className="w-full h-64 bg-black rounded" />
      </div>
    </div>
  );
};

export default CoworkingRoom;
